{"purpose":"T03 summarize CTest evidence counts from saved stdout","runtime":"python3","script":"from pathlib import Path
for label, path in [
    ('debug full CTest', Path('.gsd/exec/d916e6bb-4da3-45ae-b93e-b501f3ff1e30.stdout')),
    ('debug package_consumer CTest', Path('.gsd/exec/1f202f2d-0493-4c47-bbe7-787a84638449.stdout')),
]:
    text = path.read_text(encoding='utf-8', errors='replace').splitlines()
    print(f'[{label}] {path}')
    for line in text[-25:]:
        if ('tests passed' in line or 'tests failed' in line or 'Total Test time' in line or 'tests did not run' in line or 'Skipped' in line or 'Test #' in line):
            print(line)
    print()","timeout_ms":60000}

